-- Smart Table initial schema (001)
-- NOTE: ids are TEXT (uuid strings generated by the app) to keep the schema
-- portable between real Postgres and the pg-mem in-memory DB used for tests.
-- Foreign keys are intentionally omitted in this skeleton; relations are
-- enforced by the application layer (see src/services). Add FK constraints
-- before production.

CREATE TABLE IF NOT EXISTS merchants (
  id TEXT PRIMARY KEY,
  square_merchant_id TEXT NOT NULL UNIQUE,
  access_token_enc TEXT NOT NULL,
  refresh_token_enc TEXT NOT NULL,
  token_expires_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS locations (
  id TEXT PRIMARY KEY,
  merchant_id TEXT NOT NULL,
  square_location_id TEXT NOT NULL UNIQUE,
  name TEXT,
  currency CHAR(3) NOT NULL DEFAULT 'CAD',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_locations_merchant ON locations(merchant_id);

CREATE TABLE IF NOT EXISTS tables (
  id TEXT PRIMARY KEY,
  location_id TEXT NOT NULL,
  name TEXT NOT NULL,
  qr_token TEXT NOT NULL UNIQUE,
  state TEXT NOT NULL DEFAULT 'FREE',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_tables_location ON tables(location_id);

CREATE TABLE IF NOT EXISTS checks (
  id TEXT PRIMARY KEY,
  table_id TEXT,
  square_order_id TEXT NOT NULL UNIQUE,
  state TEXT NOT NULL DEFAULT 'OPEN',
  total_cents INTEGER NOT NULL DEFAULT 0,
  currency CHAR(3) NOT NULL DEFAULT 'CAD',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_checks_table ON checks(table_id);

CREATE TABLE IF NOT EXISTS payments (
  id TEXT PRIMARY KEY,
  check_id TEXT NOT NULL,
  square_payment_id TEXT,
  amount_cents INTEGER NOT NULL,
  tip_cents INTEGER NOT NULL DEFAULT 0,
  split_mode TEXT,
  payer_label TEXT,
  status TEXT NOT NULL DEFAULT 'PENDING',
  idempotency_key TEXT NOT NULL UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_payments_check ON payments(check_id);

CREATE TABLE IF NOT EXISTS events (
  id TEXT PRIMARY KEY,
  table_id TEXT,
  check_id TEXT,
  type TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_events_table ON events(table_id);
CREATE INDEX IF NOT EXISTS idx_events_check ON events(check_id);

CREATE TABLE IF NOT EXISTS webhook_events (
  square_event_id TEXT PRIMARY KEY,
  type TEXT,
  processed_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
